import { PageHeader } from '@/components/shared/PageHeader';
import { createServiceRoleClient } from '@/lib/supabase/service-role';
import { AdminUsersTable } from '@/features/admin/AdminUsersTable';
import type { Profile } from '@/types';

interface UserQueryResult {
  id: string;
  email: string;
  display_name: string;
  bio: string;
  website: string;
  avatar_url: string;
  subscription_tier: 'free' | 'pro';
  role: 'user' | 'admin';
  created_at: string;
}

export default async function AdminPage() {
  // Security: use service role client — NEVER anon client here
  const supabase = createServiceRoleClient();

  const { data: usersData } = await supabase
    .from('profiles')
    .select('id, email, display_name, bio, website, avatar_url, subscription_tier, role, created_at')
    .order('created_at', { ascending: false });

  const users: Profile[] = (usersData as UserQueryResult[] || []).map((user) => ({
    id: user.id,
    email: user.email,
    displayName: user.display_name,
    bio: user.bio,
    website: user.website,
    avatarUrl: user.avatar_url,
    subscriptionTier: user.subscription_tier,
    role: user.role,
    createdAt: user.created_at,
  }));

  return (
    <>
      <PageHeader
        title="Admin Panel"
        description="Manage users and system settings"
      />
      <div className="mt-8">
        <AdminUsersTable users={users} />
      </div>
    </>
  );
}

import { redirect } from 'next/navigation';
import { createClient } from '@/lib/supabase/server';
import { createServiceRoleClient } from '@/lib/supabase/service-role';

export default async function AdminLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();

  // Check user authenticated — if not redirect to /login
  if (!user) {
    redirect('/login');
  }

  // Security: role verified both in middleware AND here — never trust middleware alone
  const serviceSupabase = createServiceRoleClient();
  const { data: profile } = await serviceSupabase
    .from('profiles')
    .select('role')
    .eq('id', user.id)
    .single();

  if (profile?.role !== 'admin') {
    redirect('/dashboard');
  }

  return (
    <div className="min-h-screen bg-[#0b0c10] font-sans text-zinc-100">
      <main className="p-8">
        <div className="mx-auto max-w-7xl">
          {children}
        </div>
      </main>
    </div>
  );
}

