import { notFound } from 'next/navigation'
import { draftMode } from 'next/headers'
import { Metadata } from 'next'
import Link from 'next/link'
import { ArrowLeft } from 'lucide-react'
import { sanityFetch } from '@/lib/sanity/live'
import { PAGE_BY_SLUG_AND_LANGUAGE_QUERY, SITE_SETTINGS_WITH_LANGUAGES_QUERY } from '@/lib/sanity/queries'
import { createClient } from '@/lib/supabase/server'
import { Header, Footer } from '@/features/layout'
import { PortableText } from '@portabletext/react'
import { isValidLanguage, defaultLanguage } from '@/lib/i18n'
import type { PortableTextBlock } from '@portabletext/types'

interface SlugPageParams {
  lang: string
  slug: string
}

interface Page {
  _id: string
  title: string
  slug?: string
  description?: string
  content?: PortableTextBlock[]
  ctaButtons?: Array<{
    label: string
    href: string
    variant?: string
    external?: boolean
    requiresAuth?: boolean
  }>
  newsletterSection?: {
    heading?: string
    description?: string
    placeholder?: string
    buttonText?: string
    enabled?: boolean
  }
  seo?: {
    metaTitle?: string
    metaDescription?: string
    ogImage?: string
  }
  publishedAt?: string
}

export async function generateMetadata(props: { params: Promise<SlugPageParams> }): Promise<Metadata> {
  const { lang, slug } = await props.params
  const langCode = isValidLanguage(lang) ? lang : defaultLanguage

  const pageResult = await sanityFetch({ 
    query: PAGE_BY_SLUG_AND_LANGUAGE_QUERY, 
    params: { slug, language: langCode }
  })
  const page = pageResult.data as Page | null

  if (!page) {
    return { title: 'Page Not Found' }
  }

  return {
    title: page.seo?.metaTitle || page.title || 'ContentFlow',
    description: page.seo?.metaDescription || page.description || undefined,
    alternates: {
      canonical: langCode === defaultLanguage ? `/${slug}` : `/${langCode}/${slug}`,
      languages: {
        'en': `/${slug}`,
        'hi': `/hi/${slug}`,
      }
    }
  }
}

export default async function LangGenericPage(props: { params: Promise<SlugPageParams> }) {
  const { lang, slug } = await props.params
  const langCode = isValidLanguage(lang) ? lang : defaultLanguage
  const { isEnabled: isDraftMode } = await draftMode()

  const [pageResult, settingsResult] = await Promise.all([
    sanityFetch({ query: PAGE_BY_SLUG_AND_LANGUAGE_QUERY, params: { slug, language: langCode } }),
    sanityFetch({ query: SITE_SETTINGS_WITH_LANGUAGES_QUERY }),
  ])

  const page = pageResult.data as Page | null
  const settings = settingsResult.data

  if (!page) {
    notFound()
  }

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()

  let userProfile = null
  if (user) {
    const { data: profile } = await supabase
      .from('profiles')
      .select('id, email, display_name, avatar_url')
      .eq('id', user.id)
      .single()

    if (profile) {
      userProfile = {
        id: profile.id,
        email: profile.email,
        displayName: profile.display_name || undefined,
        avatarUrl: profile.avatar_url || undefined,
      }
    }
  }

  const supportedLanguages = settings?.supportedLanguages || [
    { _id: 'en-id', id: 'en', title: 'English', nativeTitle: 'English' },
    { _id: 'hi-id', id: 'hi', title: 'Hindi', nativeTitle: 'हिन्दी' },
  ]

