import { notFound } from 'next/navigation'
import { draftMode } from 'next/headers'
import { createClient } from '@/lib/supabase/server'
import { Header, Footer } from '@/features/layout'
import { BlogPostCard } from '@/features/posts/BlogPostCard'
import { BlogContent } from '@/features/posts/BlogContent'
import { sanityFetch } from '@/lib/sanity/live'
import { 
  PAGE_BY_TYPE_AND_LANGUAGE_QUERY, 
  SITE_SETTINGS_WITH_LANGUAGES_QUERY, 
  ALL_POSTS_BY_LANGUAGE_QUERY 
} from '@/lib/sanity/queries'
import { isValidLanguage, defaultLanguage } from '@/lib/i18n'
import type { Metadata } from 'next'

interface LangPageProps {
  params: Promise<{ lang: string }>
}

interface Language {
  _id: string
  id: string
  title: string
  nativeTitle?: string
  isDefault?: boolean
  flag?: string
}

interface Post {
  _id: string
  title: string
  slug: string
  excerpt?: string
  publishedAt?: string
  featured?: boolean
  tags?: string[]
  author?: { name: string; avatar?: string }
  coverImage?: string
}

export async function generateMetadata({ params }: LangPageProps): Promise<Metadata> {
  const { lang } = await params
  const langCode = isValidLanguage(lang) ? lang : defaultLanguage

  const settingsResult = await sanityFetch({ query: SITE_SETTINGS_WITH_LANGUAGES_QUERY })
  const settings = settingsResult.data

  return {
    title: settings?.siteName || 'ContentFlow',
    description: settings?.siteDescription || 'A modern publishing platform',
    alternates: {
      canonical: langCode === defaultLanguage ? '/' : `/${langCode}`,
      languages: {
        'en': '/',
        'hi': '/hi',
      }
    }
  }
}

export default async function LangHomePage({ params }: LangPageProps) {
  const { lang } = await params
  const langCode = isValidLanguage(lang) ? lang : defaultLanguage
  const { isEnabled: isDraftMode } = await draftMode()

  const [settingsResult, homePageResult, postsResult] = await Promise.all([
    sanityFetch({ query: SITE_SETTINGS_WITH_LANGUAGES_QUERY }),
    sanityFetch({ 
      query: PAGE_BY_TYPE_AND_LANGUAGE_QUERY, 
      params: { pageType: 'home', language: langCode }
    }),
    sanityFetch({ 
      query: ALL_POSTS_BY_LANGUAGE_QUERY, 
      params: { language: langCode }
    }),
  ])

  const settings = settingsResult.data
  const homePage = homePageResult.data
  const posts: Post[] = postsResult.data || []

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()

  let userProfile = null
  if (user) {
    const { data: profile } = await supabase
      .from('profiles')
      .select('id, email, display_name, avatar_url')
      .eq('id', user.id)
      .single()

    if (profile) {
      userProfile = {
        id: profile.id,
        email: profile.email,
        displayName: profile.display_name || undefined,
        avatarUrl: profile.avatar_url || undefined,
      }
    }
  }

  const allTags: string[] = Array.from(
    new Set(posts.flatMap((post: Post) => post.tags || []))
  ).sort()

  const featuredPost = homePage?.featuredPost || posts.find((post: Post) => post.featured) || posts[0]
  const remainingPosts = posts.filter((post: Post) => post._id !== featuredPost?._id)

  const supportedLanguages: Language[] = settings?.supportedLanguages || [
    { _id: 'en-id', id: 'en', title: 'English', nativeTitle: 'English', isDefault: true },
    { _id: 'hi-id', id: 'hi', title: 'Hindi', nativeTitle: 'हिन्दी', isDefault: false },
  ]

  return (
    <div className="min-h-screen bg-[#0b0c10]">
      <Header
        siteName={settings?.siteName}
        headerNav={settings?.headerNav ?? undefined}
        guestNav={settings?.guestNav ?? undefined}
        authNav={settings?.authNav ?? undefined}
        lang={langCode}
        supportedLanguages={supportedLanguages}
        user={userProfile}
      />

      {isDraftMode && (
        <div className="bg-amber-500/10 border-b border-amber-500/20">
          <div className="mx-auto max-w-6xl px-12 lg:px-32 py-3">
            <div className="flex items-center justify-between">
              <span className="text-amber-200 text-sm">
                Preview Mode — Draft content visible
              </span>
              <a
                href="/api/draft/disable"
                className="text-sm text-amber-400 hover:text-amber-300"
              >
                Exit Preview
              </a>
            </div>
          </div>
        </div>
      )}

      <main className="mx-auto max-w-6xl px-12 lg:px-32 py-12">
        {homePage?.showFeaturedPost !== false && featuredPost && (
          <section className="my-16 py-12 border-y border-white/[0.04]">
            <div className="mb-8">
              <span className="text-xs font-semibold text-[#6154f0] uppercase tracking-wider">
                {homePage?.heroSection?.featuredLabel ?? 'Featured Story'}
              </span>
            </div>
            <BlogPostCard post={featuredPost} featured />
          </section>
        )}

        <BlogContent
          posts={remainingPosts}
          featuredPost={featuredPost}
          allTags={allTags}
          title={homePage?.blogSection?.title ?? 'Latest Stories'}
          subtitle={homePage?.blogSection?.subtitle ?? 'Thoughts, tutorials, and insights'}
          emptyMessage={homePage?.blogSection?.emptyMessage ?? 'No stories found'}
          emptyDescription={homePage?.blogSection?.emptyDescription ?? 'Try adjusting your search'}
          latestArticlesLabel={homePage?.blogSection?.latestArticlesLabel ?? 'Latest Articles'}
          discoverLabel={homePage?.blogSection?.discoverLabel ?? 'Discover'}
        />
      </main>

      <Footer
        siteName={settings?.siteName}
        footerDescription={settings?.footerDescription}
        copyrightText={settings?.copyrightText}
        legalLinks={settings?.legalLinks}
        footerNav={settings?.footerNav ?? undefined}
        footerCTAButtons={homePage?.footerCTA?.buttons ?? undefined}
        newsletterSection={homePage?.newsletterSection ?? undefined}
        user={userProfile}
      />
    </div>
  )
}

