import { notFound } from 'next/navigation'
import { draftMode } from 'next/headers'
import Image from 'next/image'
import Link from 'next/link'
import dynamic from 'next/dynamic'
import { ArrowLeft, Clock } from 'lucide-react'
import { Metadata } from 'next'

import { sanityFetch } from '@/lib/sanity/live'
import { POST_BY_SLUG_AND_LANGUAGE_QUERY, SITE_SETTINGS_WITH_LANGUAGES_QUERY, PAGE_BY_TYPE_AND_LANGUAGE_QUERY } from '@/lib/sanity/queries'
import { createClient } from '@/lib/supabase/server'
import { Header, Footer } from '@/features/layout'
import { Badge } from '@/components/ui/badge'
import { LoadingSpinner } from '@/components/shared/LoadingSpinner'
import { isValidLanguage, defaultLanguage } from '@/lib/i18n'
import type { PortableTextBlock } from '@portabletext/types'

interface ExtendedPost {
  _id: string
  title: string
  slug: string
  excerpt?: string
  body?: PortableTextBlock[]
  publishedAt?: string
  featured?: boolean
  tags?: string[]
  author?: { name: string; avatar?: string; bio?: string }
  coverImage?: string
  readingTime?: number
}

interface PostPageParams {
  lang: string
  slug: string
}

const PortableTextRenderer = dynamic(
  () => import('@/features/posts/PortableTextRenderer'),
  { loading: () => <div className="py-20 flex justify-center"><LoadingSpinner size="lg" /></div> }
)

export async function generateMetadata(props: { params: Promise<PostPageParams> }): Promise<Metadata> {
  const { lang, slug } = await props.params
  const langCode = isValidLanguage(lang) ? lang : defaultLanguage
  const { isEnabled: isDraftMode } = await draftMode()

  const postResult = await sanityFetch({ 
    query: POST_BY_SLUG_AND_LANGUAGE_QUERY, 
    params: { slug, language: langCode }
  })
  const post = postResult.data as ExtendedPost | null

  if (!post) {
    return { title: 'Post Not Found' }
  }

  return {
    title: `${post.title} | ContentFlow`,
    description: post.excerpt || undefined,
    alternates: {
      canonical: langCode === defaultLanguage ? `/posts/${slug}` : `/${langCode}/posts/${slug}`,
      languages: {
        'en': `/posts/${slug}`,
        'hi': `/hi/posts/${slug}`,
      }
    }
  }
}

export default async function LangPostPage(props: { params: Promise<PostPageParams> }) {
  const { lang, slug } = await props.params
  const langCode = isValidLanguage(lang) ? lang : defaultLanguage
  const { isEnabled: isDraftMode } = await draftMode()

  const [postResult, settingsResult, homePageResult] = await Promise.all([
    sanityFetch({ query: POST_BY_SLUG_AND_LANGUAGE_QUERY, params: { slug, language: langCode } }),
    sanityFetch({ query: SITE_SETTINGS_WITH_LANGUAGES_QUERY }),
    sanityFetch({ query: PAGE_BY_TYPE_AND_LANGUAGE_QUERY, params: { pageType: 'home', language: langCode } }),
  ])

  const post = postResult.data as ExtendedPost | null
  const settings = settingsResult.data
  const homePage = homePageResult.data

  if (!post) {
    notFound()
  }

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()

  let userProfile = null
  if (user) {
    const { data: profile } = await supabase
      .from('profiles')
      .select('id, email, display_name, avatar_url')
      .eq('id', user.id)
      .single()

    if (profile) {
      userProfile = {
        id: profile.id,
        email: profile.email,
        displayName: profile.display_name || undefined,
        avatarUrl: profile.avatar_url || undefined,
      }
    }
  }

  const wordCount = post.body ? JSON.stringify(post.body).split(/\s+/).length : 0
  const readingTime = Math.ceil(wordCount / 200)

  const supportedLanguages = settings?.supportedLanguages || [
    { _id: 'en-id', id: 'en', title: 'English', nativeTitle: 'English' },
    { _id: 'hi-id', id: 'hi', title: 'Hindi', nativeTitle: 'हिन्दी' },
  ]

  const langHref = (path: string) => langCode === defaultLanguage ? path : `/${langCode}${path}`

  return (
    <div className="min-h-screen bg-[#0b0c10]">
      <Header
        siteName={settings?.siteName}
        headerNav={settings?.headerNav ?? undefined}
        guestNav={settings?.guestNav ?? undefined}
        authNav={settings?.authNav ?? undefined}
        lang={langCode}
        supportedLanguages={supportedLanguages}
        user={userProfile}
      />

      {isDraftMode && (
        <div className="bg-amber-500/10 border-b border-amber-500/20">
          <div className="mx-auto max-w-4xl px-4 sm:px-6 lg:px-8 py-3">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <span className="text-amber-400">⚠️</span>
                <span className="text-amber-200 text-sm font-medium">Preview Mode — Draft content visible</span>
              </div>
              <a
                href="/api/draft/disable"
                className="text-xs font-semibold text-amber-400 hover:text-amber-300 transition-colors"
              >
                Exit Preview →
              </a>
            </div>
          </div>
        </div>
      )}

      <main className="mx-auto max-w-4xl px-4 sm:px-6 lg:px-8 py-8 sm:py-12">
        <div className="mb-8">
          <Link
            href={langHref('/')}
            className="inline-flex items-center gap-2 text-sm text-zinc-400 hover:text-white transition-colors"
          >
            <ArrowLeft className="h-4 w-4" />
            Back to Blog
          </Link>
        </div>

        <article className="space-y-6 sm:space-y-8">
          <div className="flex flex-wrap gap-2">
            {post.tags?.map((tag) => (
              <Link key={tag} href={langHref(`/?tag=${tag}`)}>
                <Badge
                  variant="secondary"
                  className="bg-white/5 hover:bg-[#6154f0]/20 text-zinc-400 hover:text-[#6154f0] text-[10px] uppercase font-bold tracking-widest border border-white/10 rounded-full px-3 py-1 transition-colors cursor-pointer"
                >
                  {tag}
                </Badge>
              </Link>
            ))}
            {post.featured && (
              <Badge className="bg-[#6154f0]/20 text-[#6154f0] text-[10px] uppercase font-bold tracking-widest border border-transparent rounded-full px-3 py-1">
                Featured
              </Badge>
            )}
          </div>

          <h1 className="text-3xl sm:text-4xl md:text-5xl font-bold text-white leading-tight">
            {post.title}
          </h1>

          <div className="flex items-center gap-4 text-sm text-zinc-400">
            <div className="flex items-center gap-3">
              <div className="relative h-10 w-10 rounded-full overflow-hidden ring-2 ring-white/10">
                {post.author?.avatar ? (
                  <Image
                    src={post.author.avatar}
                    alt={post.author.name || 'Author'}
                    fill
                    className="object-cover"
                  />
                ) : (
                  <div className="h-full w-full bg-[#6154f0] flex items-center justify-center text-sm font-bold text-white">
                    {(post.author?.name || 'A').charAt(0)}
                  </div>
                )}
              </div>
              <div>
                <p className="font-medium text-white">{post.author?.name || 'Unknown Author'}</p>
                <div className="flex items-center gap-2 text-xs">
                  <span>{new Date(post.publishedAt || new Date()).toLocaleDateString('en-US', {
                    month: 'long',
                    day: 'numeric',
                    year: 'numeric'
                  })}</span>
                  <span className="w-1 h-1 rounded-full bg-zinc-600" />
                  <span className="flex items-center gap-1">
                    <Clock className="h-3 w-3" />
                    {readingTime} min read
                  </span>
                </div>
              </div>
            </div>
          </div>

          {post.coverImage && (
            <div className="relative w-full aspect-[16/9] overflow-hidden rounded-[16px] shadow-2xl">
              <Image
                src={post.coverImage}
                alt={post.title}
                fill
                priority
                className="object-cover"
                sizes="(max-width: 896px) 100vw, 896px"
              />
            </div>
          )}

          <div className="pt-8 border-t border-white/5">
            <PortableTextRenderer value={post.body as PortableTextBlock[]} />
          </div>
        </article>

        <div className="mt-16 pt-8 border-t border-white/5">
          <Link
            href={langHref('/')}
            className="inline-flex items-center gap-2 text-sm text-zinc-400 hover:text-white transition-colors"
          >
            <ArrowLeft className="h-4 w-4" />
            Read more articles
          </Link>
        </div>
      </main>

      <Footer
        siteName={settings?.siteName}
        footerDescription={settings?.footerDescription}
        copyrightText={settings?.copyrightText}
        legalLinks={settings?.legalLinks}
        footerNav={settings?.footerNav ?? undefined}
        footerCTAButtons={homePage?.footerCTA?.buttons ?? undefined}
        newsletterSection={homePage?.newsletterSection ?? undefined}
        user={userProfile}
      />
    </div>
  )
}

'use server';

import { createClient } from '@/lib/supabase/server';
import { createServiceRoleClient } from '@/lib/supabase/service-role';

export async function deleteAccount(
  accountId: string
): Promise<{ success: true } | { success: false; error: string }> {
  try {
    const supabaseSession = await createClient();
    const { data: { user }, error: sessionError } = await supabaseSession.auth.getUser();

    if (sessionError || !user) {
      return { success: false, error: 'Unauthorized user request' };
    }

    if (user.id !== accountId) {
      return { success: false, error: 'Authorization mismatch against active entity ID' };
    }

    const adminClient = createServiceRoleClient();
    const { error: deletionError } = await adminClient.auth.admin.deleteUser(accountId);

    if (deletionError) {
      return { success: false, error: deletionError.message };
    }

    return { success: true };
  } catch (error: unknown) {
    return { success: false, error: (error as Error).message || 'Server error occurred during execution' };
  }
}

