                >
                  {user.role}
                </Badge>
              </TableCell>
              <TableCell className="text-zinc-400 text-sm">
                {formatDate(user.createdAt)}
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
      </div>
    </div>
  );
}

