'use client';

import { useState, useMemo } from 'react';
import { Search, ArrowRight, X } from 'lucide-react';
import { BlogPostCard } from '@/features/posts/BlogPostCard';
import { useDebounce } from '@/hooks/useDebounce';
import type { Post } from '@/types';

interface BlogContentProps {
  posts: Post[];
  featuredPost: Post | null;
  allTags: string[];
  title?: string;
  subtitle?: string;
  emptyMessage?: string;
  emptyDescription?: string;
  latestArticlesLabel?: string;
  discoverLabel?: string;
}

export function BlogContent({ 
  posts, 
  allTags, 
  title = 'Latest Stories', 
  subtitle = 'Thoughts, tutorials, and insights',
  emptyMessage = 'No stories found',
  emptyDescription = 'Try adjusting your search',
  latestArticlesLabel = 'Latest Articles',
  discoverLabel = 'Discover',
}: BlogContentProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [activeTag, setActiveTag] = useState('all');

  const debouncedSearchQuery = useDebounce(searchQuery, 300);

  const filteredPosts = useMemo(() => {
    const query = debouncedSearchQuery.toLowerCase().trim();

    return posts.filter(post => {
      const matchesSearch = !query || 
        post.title.toLowerCase().includes(query) || 
        (post.excerpt || '').toLowerCase().includes(query) ||
        (post.tags || []).some(tag => tag.toLowerCase().includes(query));

      const matchesTag = activeTag === 'all' || (post.tags || []).includes(activeTag);

      return matchesSearch && matchesTag;
    });
  }, [posts, debouncedSearchQuery, activeTag]);

  const handleClearFilters = () => {
    setSearchQuery('');
    setActiveTag('all');
  };

  return (
    <div>
      {/* Search and Tags Bar */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 mb-10 pb-6">
        <div>
          <h2 className="text-2xl font-bold text-white mb-1">{title}</h2>
          <p className="text-zinc-500 text-sm">{subtitle}</p>
        </div>

        <div className="flex items-center gap-4">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-zinc-500" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search..."
              className="w-64 rounded-full border border-white/[0.08] bg-[#121319] pl-9 pr-8 py-2 text-sm text-white placeholder:text-zinc-600 focus:outline-none focus:border-[#6154f0]/50 transition-colors"
            />
            {searchQuery && (
              <button
                onClick={() => setSearchQuery('')}
                className="absolute right-2 top-1/2 -translate-y-1/2 p-1 text-zinc-500 hover:text-white"
              >
                <X className="h-3 w-3" />
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Tag Filters */}
      {allTags.length > 0 && (
        <div className="flex items-center gap-2 overflow-x-auto pb-4 mb-8 border-b border-white/[0.04] scrollbar-hide">
          <button
            onClick={() => setActiveTag('all')}
            className={`px-4 py-1.5 rounded-full text-sm font-medium whitespace-nowrap transition-colors ${
              activeTag === 'all'
                ? 'bg-white text-[#0b0c10]'
                : 'bg-transparent text-zinc-500 hover:text-white'
            }`}
          >
            All
          </button>
          {allTags.map((tag) => (
            <button
              key={tag}
              onClick={() => setActiveTag(tag)}
              className={`px-4 py-1.5 rounded-full text-sm font-medium whitespace-nowrap transition-colors ${
                activeTag === tag
                  ? 'bg-[#6154f0] text-white'
                  : 'bg-transparent text-zinc-500 hover:text-white'
              }`}
            >
              {tag}
            </button>
          ))}
        </div>
      )}

      {filteredPosts.length === 0 ? (
        <div className="text-center py-20 border-t border-white/[0.04]">
          <div className="w-16 h-16 rounded-full bg-[#121319] flex items-center justify-center mx-auto mb-4">
            <Search className="h-6 w-6 text-zinc-600" />
          </div>
          <h3 className="text-xl font-semibold text-white mb-2">{emptyMessage}</h3>
          <p className="text-zinc-500 mb-6">{emptyDescription}</p>
          <button 
            onClick={handleClearFilters}
            className="inline-flex items-center gap-2 px-5 py-2.5 bg-white text-[#0b0c10] rounded-full font-medium hover:bg-zinc-200 transition-colors"
          >
            Clear
            <ArrowRight className="h-4 w-4" />
          </button>
        </div>
      ) : (
        <>
          {/* Section Header */}
          <div className="flex items-center justify-between mb-8 pb-4 border-b border-white/[0.04]">
            <h3 className="text-sm font-semibold text-white uppercase tracking-wide">{latestArticlesLabel}</h3>
            <p className="text-sm text-zinc-500">
              {filteredPosts.length} {filteredPosts.length === 1 ? 'story' : 'stories'}
            </p>
          </div>

          {/* Articles Grid - Medium Style */}
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-x-12">
            {/* Main Column */}
            <div className="lg:col-span-8">
              {filteredPosts.map((post, index) => (
                <BlogPostCard 
                  key={post._id} 
                  post={post} 
                  horizontal 
                  isFirst={index === 0}
                />
              ))}
            </div>

            {/* Sidebar - Optional, could show trending or tags */}
            <div className="hidden lg:block lg:col-span-4">
              <div className="sticky top-24 pt-2">
                <h3 className="text-sm font-semibold text-white mb-4 uppercase tracking-wide">{discoverLabel}</h3>
                <div className="flex flex-wrap gap-2">
                  {allTags.slice(0, 10).map((tag) => (
                    <button
                      key={tag}
                      onClick={() => setActiveTag(tag)}
                      className="px-3 py-1.5 bg-[#121319] text-zinc-400 text-sm rounded-full hover:text-white transition-colors"
                    >
                      {tag}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

'use client';

import Image from 'next/image';
import Link from 'next/link';
import { Clock } from 'lucide-react';
import type { Post } from '@/types';

interface BlogPostCardProps {
  post: Post;
  featured?: boolean;
  horizontal?: boolean;
  isFirst?: boolean;
}

function calculateReadingTime(content?: string): number {
  if (!content) return 3;
  const wordsPerMinute = 200;
  const words = content.split(/\s+/).length;
  return Math.ceil(words / wordsPerMinute);
}

function AuthorAvatar({ name, avatar }: { name: string; avatar?: string | null }) {
  return (
    <div className="relative h-6 w-6 rounded-full overflow-hidden bg-[#6154f0] flex-shrink-0">
      {avatar ? (
        <Image 
          src={avatar} 
          alt={name}
          fill 
          className="object-cover"
        />
      ) : (
        <div className="h-full w-full flex items-center justify-center text-xs font-semibold text-white">
          {name.charAt(0).toUpperCase()}
        </div>
      )}
    </div>
  );
}

export function BlogPostCard({ post, featured = false, horizontal = false, isFirst = false }: BlogPostCardProps) {
  const formattedDate = post.publishedAt 
    ? new Date(post.publishedAt).toLocaleDateString('en-US', { 
        month: 'short',
        day: 'numeric'
      })
    : null;

  const readingTime = calculateReadingTime(post.excerpt ?? undefined);
  const tags = post.tags ?? [];

  if (featured) {
    return (
      <Link href={`/posts/${post.slug}`} className="group block">
        <article className="flex flex-row gap-5 md:gap-8">
          {/* Image - Left side */}
          <div className="relative w-32 h-32 md:w-56 md:h-40 bg-[#121319] rounded-lg overflow-hidden flex-shrink-0">
            {post.coverImage ? (
              <Image
                src={post.coverImage}
                alt={post.title}
                fill
                className="object-cover group-hover:scale-105 transition-transform duration-500"
                sizes="224px"
                priority
              />
            ) : (
              <div className="w-full h-full bg-[#121319] flex items-center justify-center">
                <div className="w-10 h-10 rounded-full bg-[#1a1a1a] flex items-center justify-center">
                  <span className="text-lg text-zinc-700">✦</span>
                </div>
              </div>
            )}
          </div>

          {/* Content - Right side */}
          <div className="flex flex-col justify-center flex-1 min-w-0">
            {tags.length > 0 && (
              <span className="text-xs font-medium text-[#6154f0] uppercase tracking-wider mb-2">
                {tags[0]}
              </span>
            )}

            <h2 className="text-lg md:text-xl font-bold text-white mb-2 leading-snug group-hover:text-zinc-300 transition-colors">
              {post.title}
            </h2>

            <p className="text-zinc-400 text-sm leading-relaxed mb-3 line-clamp-2 hidden md:block">
              {post.excerpt || 'No excerpt available'}
            </p>

            <div className="flex items-center gap-2 flex-wrap">
              <AuthorAvatar name={post.author?.name || 'A'} avatar={post.author?.avatar} />
              <div className="flex items-center gap-1.5 text-sm text-zinc-500">
                <span className="text-zinc-300 font-medium">{post.author?.name || 'Unknown'}</span>
                <span className="text-zinc-600">·</span>
                <span>{formattedDate}</span>
                <span className="text-zinc-600">·</span>
                <span className="flex items-center gap-1">
                  <Clock className="h-3 w-3" />
                  {readingTime} min
                </span>
              </div>
            </div>
          </div>
        </article>
      </Link>
    );
  }

  // Medium-style horizontal article card
  return (
    <Link 
      href={`/posts/${post.slug}`}
      className="group block"
    >
      <article className="flex gap-5 md:gap-6 py-8 border-b border-white/[0.04] last:border-b-0">
        {/* Content - Takes available space */}
        <div className="flex-1 min-w-0 flex flex-col justify-center">
          {/* Author & Meta */}
          <div className="flex items-center gap-2 mb-2">
            <AuthorAvatar name={post.author?.name || 'A'} avatar={post.author?.avatar} />
            <span className="text-sm font-medium text-zinc-300">{post.author?.name || 'Unknown'}</span>
            {formattedDate && (
              <>
                <span className="text-zinc-600">·</span>
                <span className="text-sm text-zinc-500">{formattedDate}</span>
              </>
            )}
          </div>

          {/* Title */}
          <h3 className={`font-bold text-white mb-2 group-hover:text-zinc-300 transition-colors leading-snug ${
            isFirst ? 'text-xl md:text-2xl' : 'text-lg md:text-xl'
          }`}>
            {post.title}
          </h3>

          {/* Excerpt */}
          <p className="text-zinc-500 text-sm leading-relaxed mb-3 line-clamp-2">
            {post.excerpt || 'No excerpt available'}
          </p>

          {/* Bottom Meta */}
          <div className="flex items-center gap-3 text-sm text-zinc-500">
            {tags.length > 0 && (
              <span className="bg-[#121319] px-2 py-0.5 rounded text-xs">
                {tags[0]}
              </span>
            )}
            <span className="flex items-center gap-1">
              <Clock className="h-3 w-3" />
              {readingTime} min read
            </span>
          </div>
        </div>

        {/* Thumbnail */}
        <div className="relative w-24 h-24 md:w-28 md:h-28 flex-shrink-0 bg-[#121319] rounded-lg overflow-hidden">
          {post.coverImage ? (
            <Image
              src={post.coverImage}
              alt={post.title}
              fill
              className="object-cover"
              sizes="112px"
            />
          ) : (
            <div className="w-full h-full bg-[#121319] flex items-center justify-center">
              <div className="w-8 h-8 rounded-full bg-[#1a1a1a] flex items-center justify-center">
                <span className="text-base text-zinc-700">✦</span>
              </div>
            </div>
          )}
        </div>
      </article>
    </Link>
  );
}

