'use client';

import { useEffect, useState, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import type { Database } from '@/types/supabase';
import type { User } from '@supabase/supabase-js';
import type { Profile } from '@/types';

type ProfileRow = Database['public']['Tables']['profiles']['Row'];

export function useUser() {
  const [user, setUser] = useState<User | null>(null);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const fetchUserAndProfile = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      const supabase = createClient();
      
      // Get current session first - this is more reliable than getUser()
      const { data: { session }, error: sessionError } = await supabase.auth.getSession();
      
      if (sessionError) {
        throw sessionError;
      }
      
      if (!session) {
        setUser(null);
        setProfile(null);
        setLoading(false);
        return;
      }

      const currentUser = session.user;
      setUser(currentUser);

      // Fetch profile
      const { data, error: profileError } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', currentUser.id)
        .single();

      if (profileError) {
        // Profile doesn't exist yet
        if (profileError.code === 'PGRST116') {
          setProfile(null);
        } else {
          setError(profileError);
          setProfile(null);
        }
      } else if (data) {
        const profileData = data as ProfileRow;
        setProfile({
          id: profileData.id,
          email: profileData.email,
          displayName: profileData.display_name || '',
          bio: profileData.bio || '',
          website: profileData.website || '',
          avatarUrl: profileData.avatar_url || '',
          subscriptionTier: profileData.subscription_tier,
          role: profileData.role,
          createdAt: profileData.created_at,
        });
      }
    } catch (err) {
      setError(err instanceof Error ? err : new Error('An unknown error occurred'));
      setProfile(null);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchUserAndProfile();

    // Subscribe to auth changes
    const supabase = createClient();
    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      async (event, session) => {
        if (event === 'SIGNED_OUT') {
          setUser(null);
          setProfile(null);
          setLoading(false);
        } else if (session) {
          setUser(session.user);
          fetchUserAndProfile();
        }
      }
    );

    return () => {
      subscription.unsubscribe();
    };
  }, [fetchUserAndProfile]);

  return { user, profile, loading, error, refetch: fetchUserAndProfile };
}

export const defaultLanguage = 'en'

export const languages = [
  { id: 'en', title: 'English', nativeTitle: 'English', isDefault: true, flag: '🇺🇸' },
  { id: 'hi', title: 'Hindi', nativeTitle: 'हिन्दी', isDefault: false, flag: '🇮🇳' },
] as const

export type LanguageId = typeof languages[number]['id']

export const languageIds = languages.map((lang) => lang.id)

export function isValidLanguage(lang: string): lang is LanguageId {
  return languageIds.includes(lang as LanguageId)
}

export function getLanguage(lang: string | undefined) {
  if (!lang) return languages.find((l) => l.isDefault) || languages[0]
  return languages.find((l) => l.id === lang) || languages.find((l) => l.isDefault) || languages[0]
}

export function getDefaultLanguage() {
  return languages.find((l) => l.isDefault) || languages[0]
}

