    copyrightText,
    footerDescription,
    socialLinks,
    legalLinks {
      privacy { label, href },
      terms { label, href },
      cookies { label, href }
    },
    headerNav[] {
      label,
      href,
      external,
      requiresAuth,
      authOnly,
      guestOnly
    },
    footerNav[] {
      title,
      items[] {
        label,
        href,
        external,
        requiresAuth
      }
    },
    dashboardNav[] {
      label,
      href,
      external,
      requiresAuth
    },
    authNav[] {
      label,
      href,
      external,
      requiresAuth
    },
    guestNav[] {
      label,
      href,
      external,
      requiresAuth
    }
  }
`

// Pages (slug-based routing)
export const PAGE_BY_TYPE_QUERY = groq`
