      emptyMessage,
      emptyDescription,
      latestArticlesLabel,
      discoverLabel
    },
    newsletterSection {
      heading,
      description,
      placeholder,
      buttonText,
      enabled
    },
    footerCTA {
      enabled,
      heading,
      description,
      buttons[] {
        label,
        href,
        variant,
        external,
        requiresAuth
      }
    },
    featuredPost->{
      _id,
      title,
      'slug': slug.current,
      excerpt,
      'coverImage': coverImage.asset->url,
      author->{ name, 'avatar': image.asset->url }
