    }),
    defineField({
      name: 'featured',
      title: 'Featured Post',
      type: 'boolean',
      initialValue: false,
      description: 'Show this post in the featured section on homepage',
    }),
    defineField({
      name: 'mostViewed',
      title: 'Most Viewed',
      type: 'boolean',
