import { defineType, defineField } from 'sanity'

export default defineType({
  name: 'post',
  title: 'Post',
  type: 'document',
  fields: [
    defineField({
      name: 'language',
      title: 'Language',
      type: 'reference',
      to: [{ type: 'language' }],
      description: 'The language of this post',
      validation: (Rule) => Rule.required(),
    }),
    defineField({
      name: 'translationOf',
      title: 'Translation Of',
      type: 'reference',
      to: [{ type: 'post' }],
      description: 'Link to the original post this is a translation of',
      options: {
        filter: ({ document }) => {
          const language = (document as { language?: { _ref?: string } })?.language?._ref
          if (!language) return { filter: 'true' }
          return {
            filter: 'language._ref != $language',
            params: { language },
          }
        },
      },
    }),
    defineField({
      name: 'title',
      title: 'Title',
      type: 'string',
      validation: (Rule) => Rule.required(),
    }),
    defineField({
      name: 'slug',
      title: 'Slug',
      type: 'slug',
      options: { source: 'title' },
      validation: (Rule) => Rule.required(),
    }),
    defineField({
      name: 'excerpt',
      title: 'Excerpt',
      type: 'text',
      rows: 3,
    }),
    defineField({
      name: 'body',
      title: 'Body',
      type: 'array',
      of: [{ type: 'block' }, { type: 'image', options: { hotspot: true } }],
    }),
    defineField({
      name: 'author',
      title: 'Author',
      type: 'reference',
      to: [{ type: 'author' }],
    }),
    defineField({
      name: 'coverImage',
      title: 'Cover Image',
      type: 'image',
      options: { hotspot: true },
    }),
    defineField({
      name: 'publishedAt',
      title: 'Published At',
      type: 'datetime',
    }),
    defineField({
      name: 'tags',
      title: 'Tags',
      type: 'array',
      of: [{ type: 'string' }],
    }),
    defineField({
      name: 'featured',
      title: 'Featured Post',
      type: 'boolean',
      initialValue: false,
      description: 'Show this post in the featured section on homepage',
    }),
    defineField({
      name: 'mostViewed',
      title: 'Most Viewed',
      type: 'boolean',
      initialValue: false,
      description: 'Mark this post as one of the most viewed',
    }),
    defineField({
      name: 'showOnHome',
      title: 'Show on Homepage',
      type: 'boolean',
      initialValue: true,
      description: 'Whether to display this post on the homepage',
    }),
    defineField({
      name: 'displayOrder',
      title: 'Display Order',
      type: 'number',
      description: 'Custom ordering (lower numbers appear first)',
      validation: (Rule) => Rule.min(0),
    }),
    defineField({
      name: 'homePageOrder',
      title: 'Home Page Order',
      type: 'number',
      description: 'Ordering specifically for homepage display',
      validation: (Rule) => Rule.min(0),
    }),
    defineField({
      name: 'readingTime',
      title: 'Reading Time (minutes)',
      type: 'number',
      description: 'Estimated reading time in minutes (auto-calculated if empty)',
    }),
    defineField({
      name: 'metaTitle',
      title: 'SEO Meta Title',
      type: 'string',
      description: 'Custom title for SEO (defaults to post title)',
    }),
    defineField({
      name: 'metaDescription',
      title: 'SEO Meta Description',
      type: 'text',
      rows: 2,
      description: 'Custom description for SEO (defaults to excerpt)',
    }),
  ],
  preview: {
    select: {
      title: 'title',
      author: 'author.name',
      media: 'coverImage',
    },
  },
})

