import { defineConfig } from 'sanity'
import { structureTool, StructureBuilder as S } from 'sanity/structure'
import { presentationTool } from 'sanity/presentation'
import { visionTool } from '@sanity/vision'
import { documentInternationalization } from '@sanity/document-internationalization'
import { schemaTypes } from './lib/sanity/schemas'

// Single-instance page types - only one of each can exist PER LANGUAGE
const singlePageTypes = ['home', 'auth', 'dashboard']

export default defineConfig({
  name: 'default',
  title: 'ContentFlow Studio',
  projectId: process.env.NEXT_PUBLIC_SANITY_PROJECT_ID || 'wk6gdzqf',
  dataset: process.env.NEXT_PUBLIC_SANITY_DATASET || 'production',
  plugins: [
    presentationTool({
      previewUrl: {
        previewMode: {
          enable: '/api/draft/enable',
        },
      },
    }),
    documentInternationalization({
      supportedLanguages: [
        { id: 'en', title: 'English' },
        { id: 'hi', title: 'Hindi' },
      ],
      schemaTypes: ['page', 'post'],
    }),
    structureTool({
      structure: (S) =>
        S.list()
          .title('Content')
          .items([
            S.listItem()
              .title('Languages')
              .icon(() => '🌐')
              .child(S.documentTypeList('language').title('Languages')),
            S.divider(),
            S.listItem()
              .title('Site Settings')
              .id('siteSettings')
              .child(
                S.document()
                  .schemaType('siteSettings')
                  .documentId('siteSettings')
              ),
            S.divider(),
            S.listItem()
              .title('Pages')
              .child(
                S.list()
                  .title('Pages by Type')
                  .items([
                    S.listItem()
                      .title('Homepage')
                      .child(
                        S.documentList()
                          .title('Homepage (by Language)')
                          .filter('pageType == "home"')
                      ),
                    S.listItem()
                      .title('Auth Pages')
                      .child(
                        S.documentList()
                          .title('Auth Pages (by Language)')
                          .filter('pageType == "auth"')
                      ),
                    S.listItem()
                      .title('Dashboard')
                      .child(
                        S.documentList()
                          .title('Dashboard (by Language)')
                          .filter('pageType == "dashboard"')
                      ),
                    S.divider(),
                    S.listItem()
                      .title('Generic Pages')
                      .child(
                        S.documentTypeList('page')
                          .title('Generic Pages')
                          .filter('pageType == "generic"')
                      ),
                  ])
              ),
            S.divider(),
            S.documentTypeListItem('post').title('Posts'),
            S.documentTypeListItem('author').title('Authors'),
          ]),
    }),
    visionTool(),
  ],
  schema: {
    types: schemaTypes,
    templates: (templates) => {
      const filtered = templates.filter(
        (template) => !singlePageTypes.includes(template.id)
      )
      return [
        ...filtered,
        {
          id: 'pageType',
          title: 'Page Type',
          schemaType: 'page',
          parameters: [{ name: 'pageType', type: 'string' }],
          value: (params: { pageType: string }) => ({
            pageType: params.pageType,
            title: params.pageType === 'home' ? 'Home' : 
                   params.pageType === 'auth' ? 'Authentication' : 
                   params.pageType === 'dashboard' ? 'Dashboard' : 'Untitled',
          }),
        },
      ]
    },
  },
  document: {
    actions: (input, context) => {
      const documentId = context.documentId
      const isSinglePage = documentId === 'page-home' || documentId === 'page-auth' || documentId === 'page-dashboard'

      if (isSinglePage) {
        return input.filter(({ action }) => action && ['publish', 'discardChanges', 'restore'].includes(action))
      }
      return input
    },
  },
})

