import { create } from 'zustand';
import { persist } from 'zustand/middleware';

interface UIState {
  sidebarOpen: boolean;
  activePath: string;
}

interface UIActions {
  toggleSidebar: () => void;
  setSidebarOpen: (open: boolean) => void;
  setActivePath: (path: string) => void;
}

// CORRECT: const sidebarOpen = useUIStore((state) => state.sidebarOpen)
// WRONG:   const store = useUIStore()

export const useUIStore = create<UIState & UIActions>()(
  persist(
    (set) => ({
      sidebarOpen: true,
      activePath: '/dashboard',
      toggleSidebar: () => set((state) => ({ sidebarOpen: !state.sidebarOpen })),
      setSidebarOpen: (open: boolean) => set({ sidebarOpen: open }),
      setActivePath: (path: string) => set({ activePath: path }),
    }),
    {
      name: 'ui-store',
      partialize: (state) => ({ sidebarOpen: state.sidebarOpen }),
    }
  )
);

export interface Author {
  _id?: string;
  name: string;
  slug?: string;
  bio?: string;
  avatar?: string | null;
}

export interface Post {
  _id: string;
  title: string;
  slug: string;
  excerpt?: string | null;
  publishedAt?: string | null;
  featured?: boolean | null;
  tags?: string[]| null;
  authorId?: string | null;
  author?: Author | null;
  coverImage?: string | null;
}

export interface Profile {
  id: string;
  email: string;
  displayName: string;
  bio: string;
  website: string;
  avatarUrl: string;
  subscriptionTier: 'free' | 'pro';
  role: 'user' | 'admin';
  stripeCustomerId?: string;
  stripeSubscriptionId?: string;
  createdAt: string;
}

export interface User {
  id: string;
  email?: string;
  app_metadata: Record<string, unknown>;
  user_metadata: Record<string, unknown>;
  aud: string;
  created_at: string;
}

import type { ReactNode } from 'react';
import type { LucideIcon } from 'lucide-react';

export interface PageHeaderProps {
  title: ReactNode;
  description?: string;
  children?: ReactNode;
}

export interface EmptyStateProps {
  icon: LucideIcon;
  title: string;
  description: string;
  action?: {
    label: string;
    onClick: () => void;
  };
}

export interface LoadingSpinnerProps {
  size?: 'sm' | 'md' | 'lg';
  className?: string;
}

export interface PostDetailPageProps {
  params: Promise<{ slug: string }>;
}

// Placeholder Database type — will be replaced by Supabase CLI generated types
// Run: npx supabase gen types typescript --project-id YOUR_PROJECT_ID > types/supabase.ts

export type Json =
  | string
  | number
  | boolean
  | null
  | { [key: string]: Json | undefined }
  | Json[];

export interface Database {
  public: {
    Tables: {
